#include <iostream>

int main() {
    int unitPrice = 25;
    int count = 4;
    count = count - 1;
    int total = unitPrice * count;
    std::cout << "remaining=" << count << "\n";
    std::cout << "total=" << total << "\n";
    return 0;
}
